# Hmm! Go's filepath.Ext considers ".gitignore" -> ".gitignore" and ".env" -> ".env"
# But the executable shows .env -> 1 and .gitignore -> 2 with no extension appended!
# So the tool doesn't use Go's ext logic for dotfiles.

# Let me check Rust's behavior:
cat > /tmp/rust_ext_test.rs << 'EOF'
use std::path::Path;

fn main() {
    let files = [".gitignore", ".env", "file.txt", "file.with.dots.txt", "noext", ".hidden.txt"];
    for f in &files {
        let ext = Path::new(f).extension();
        println!("{} -> {:?}", f, ext);
    }
}
EOF

