package main

import (
    "fmt"
    "strings"
)

// rustExtension returns the extension of a filename, mimicking Rust's Path::extension()
func rustExtension(filename string) string {
    // Base name only (no directory)
    // If starts with ".", strip that leading dot first
    s := filename
    if strings.HasPrefix(s, ".") {
        s = s[1:]
    }
    idx := strings.LastIndex(s, ".")
    if idx < 0 {
        return ""
    }
    return s[idx:]
}

func main() {
    files := []string{".gitignore", ".env", "file.txt", "file.with.dots.txt", "noext", ".hidden.txt"}
    for _, f := range files {
        fmt.Printf("%s -> '%s'\n", f, rustExtension(f))
    }
}
EOF

