type appConfig struct {
	dir      string
	depth    int // 0 = not set
	maxDepth int // 0 = not set
	noExt    bool
	generate string
	mkdir    bool
	mapFile  string
	quiet    bool
	regex    string
	sortOrder string // "asc", "desc", ""
	testMode bool
	overwrite bool
	// positional args
	posArgs []string
}

func parseArgs(args []string) (*appConfig, error) {
	cfg := &appConfig{}

	i := 0
	for i < len(args) {
		arg := args[i]

		switch {
		case arg == "--help" || arg == "-h":
			if arg == "--help" {
				printUsage()
			} else {
				printShortUsage()
			}
			os.Exit(0)
		case arg == "--version" || arg == "-V":
			fmt.Printf("%s %s\n", appName, version)
			os.Exit(0)
		case arg == "-d" || arg == "--dir":
			i++
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: '%s'", arg)
			}
			cfg.dir = args[i]
		case strings.HasPrefix(arg, "-d"):
			cfg.dir = arg[2:]
		case strings.HasPrefix(arg, "--dir="):
			cfg.dir = arg[6:]
		case arg == "--depth":
			i++
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: '%s'", arg)
			}
			n, err := strconv.Atoi(args[i])
			if err != nil {
				return nil, fmt.Errorf("invalid value '%s' for '--depth'", args[i])
			}
			cfg.depth = n
		case strings.HasPrefix(arg, "--depth="):
			n, err := strconv.Atoi(arg[8:])
			if err != nil {
				return nil, fmt.Errorf("invalid value for '--depth'")
			}
			cfg.depth = n
		case arg == "--max-depth":
			i++
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: '%s'", arg)
			}
			n, err := strconv.Atoi(args[i])
			if err != nil {
				return nil, fmt.Errorf("invalid value '%s' for '--max-depth'", args[i])
			}
			cfg.maxDepth = n
		case strings.HasPrefix(arg, "--max-depth="):
			n, err := strconv.Atoi(arg[12:])
			if err != nil {
				return nil, fmt.Errorf("invalid value for '--max-depth'")
			}
			cfg.maxDepth = n
		case arg == "-E" || arg == "--no-extension":
			cfg.noExt = true
		case arg == "-g" || arg == "--generate":
			i++
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: '%s'", arg)
			}
			cfg.generate = args[i]
		case strings.HasPrefix(arg, "-g"):
			cfg.generate = arg[2:]
		case strings.HasPrefix(arg, "--generate="):
			cfg.generate = arg[11:]
		case arg == "-k" || arg == "--mkdir":
			cfg.mkdir = true
		case arg == "-m" || arg == "--map" || arg == "--from-file":
			i++
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: '%s'", arg)
			}
			cfg.mapFile = args[i]
		case strings.HasPrefix(arg, "-m"):
			cfg.mapFile = arg[2:]
		case strings.HasPrefix(arg, "--map="):
			cfg.mapFile = arg[6:]
		case strings.HasPrefix(arg, "--from-file="):
			cfg.mapFile = arg[12:]
		case arg == "-q" || arg == "--quiet":
			cfg.quiet = true
		case arg == "-r" || arg == "--regex":
			i++
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: '%s'", arg)
			}
			cfg.regex = args[i]
		case strings.HasPrefix(arg, "-r"):
			cfg.regex = arg[2:]
		case strings.HasPrefix(arg, "--regex="):
			cfg.regex = arg[8:]
		case arg == "-s" || arg == "--sort":
			i++
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: '%s'", arg)
			}
			val := args[i]
			if val != "asc" && val != "desc" {
				return nil, fmt.Errorf("invalid value '%s' for '--sort <ORDER>'\n  [possible values: asc, desc]\n\nFor more information, try '--help'.", val)
			}
			cfg.sortOrder = val
		case strings.HasPrefix(arg, "-s"):
			val := arg[2:]
			if val != "asc" && val != "desc" {
				return nil, fmt.Errorf("invalid value '%s' for '--sort <ORDER>'\n  [possible values: asc, desc]\n\nFor more information, try '--help'.", val)
			}
			cfg.sortOrder = val
		case strings.HasPrefix(arg, "--sort="):
			val := arg[7:]
			if val != "asc" && val != "desc" {
				return nil, fmt.Errorf("invalid value '%s' for '--sort <ORDER>'\n  [possible values: asc, desc]\n\nFor more information, try '--help'.", val)
			}
			cfg.sortOrder = val
		case arg == "-t" || arg == "--test" || arg == "--dry-run":
			cfg.testMode = true
		case arg == "-w" || arg == "--overwrite":
			cfg.overwrite = true
		case strings.HasPrefix(arg, "-") && len(arg) > 1:
			return nil, fmt.Errorf("error: unexpected argument '%s' found\n\nFor more information, try '--help'.", arg)
		default:
			cfg.posArgs = append(cfg.posArgs, arg)
		}
		i++
	}

	return cfg, nil
}

// ===== Walk for sort mode =====

func walkForSort(workDir string) ([]fileEntry, error) {
	dirEntries, err := os.ReadDir(workDir)
	if err != nil {
		return nil, err
	}
	var entries []fileEntry
	for _, de := range dirEntries {
		entries = append(entries, fileEntry{relPath: de.Name(), isDir: de.IsDir()})
	}
	return entries, nil
}

// walkAll walks all files in directory for map mode
func walkAll(workDir string) ([]fileEntry, error) {
	var entries []fileEntry
	err := filepath.WalkDir(workDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(workDir, path)
		if rel == "." {
			return nil
		}
		entries = append(entries, fileEntry{relPath: rel, isDir: d.IsDir()})
		return nil
	})
	return entries, err
}

// ===== Main =====

func main() {
	args := os.Args[1:]

	cfg, err := parseArgs(args)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n\nUsage: %s [OPTIONS] [[SOURCE] OUTPUT]...\n\nFor more information, try '--help'.\n", err, appName)
		os.Exit(2)
	}

	// Set working directory
	workDir := "."
	if cfg.dir != "" {
		workDir = cfg.dir
	}

	// Change to work directory
	if workDir != "." {
		if err := os.Chdir(workDir); err != nil {
			fmt.Fprintf(os.Stderr, "[error] unable to change directory to '%s': %v\n", workDir, err)
			os.Exit(1)
		}
		workDir = "."
	}

	preserveExt := !cfg.noExt

	var renameEntries []renameEntry

	// Determine mode
	if cfg.mapFile != "" {
		// Map mode
		entries, err := computeMapRename(cfg.mapFile, cfg.overwrite, cfg.testMode)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		renameEntries = entries

	} else if cfg.sortOrder != "" {
		// Sort mode
		var outputPattern string

		// Check if there are positional args for the output pattern
		if len(cfg.posArgs) >= 2 {
			// Last pair: posArgs[-2] is regex (filter), posArgs[-1] is output
			// Actually in sort mode, the last positional arg is the output pattern
			// And there might be a source regex from either -r or last-2 positional
			// But based on observed behavior: the LAST arg is always output
			// and if 2+ args, the second-to-last is the source (filter)
			outputPattern = cfg.posArgs[len(cfg.posArgs)-1]
			if cfg.regex == "" {
				cfg.regex = cfg.posArgs[len(cfg.posArgs)-2]
			}
		} else if len(cfg.posArgs) == 1 {
			outputPattern = cfg.posArgs[0]
		} else {
			// Error: no output pattern
			fmt.Fprintln(os.Stderr, "error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\nusage: run '"+appName+" --help' for more information.")
			os.Exit(1)
		}

		allEntries, err := walkForSort(workDir)
		if err != nil {
			fmt.Fprintf(os.Stderr, "[error] unable to read directory: %v\n", err)
			os.Exit(1)
		}

		// Apply regex filter if set
		var filteredEntries []fileEntry
		if cfg.regex != "" {
			re, err := regexp.Compile(cfg.regex)
			if err != nil {
				fmt.Fprintf(os.Stderr, "[error] invalid regex: %v\n", err)
				os.Exit(1)
			}
			for _, e := range allEntries {
				if re.MatchString(e.relPath) {
					filteredEntries = append(filteredEntries, e)
				}
			}
		} else {
			filteredEntries = allEntries
		}

		entries, err := computeSortRename(filteredEntries, outputPattern, cfg.sortOrder == "asc", preserveExt, workDir, cfg.overwrite, cfg.testMode)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		renameEntries = entries

	} else if cfg.regex != "" || len(cfg.posArgs) >= 2 {
		// Regex mode
		var regexPattern, outputPattern string

		if len(cfg.posArgs) >= 2 {
			// Last 2 positional args: SOURCE OUTPUT
			outputPattern = cfg.posArgs[len(cfg.posArgs)-1]
			if cfg.regex == "" {
				regexPattern = cfg.posArgs[len(cfg.posArgs)-2]
			} else {
				regexPattern = cfg.regex
			}
		} else {
			regexPattern = cfg.regex
			if len(cfg.posArgs) == 1 {
				outputPattern = cfg.posArgs[0]
			} else {
				fmt.Fprintln(os.Stderr, "error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\nusage: run '"+appName+" --help' for more information.")
				os.Exit(1)
			}
		}

		// Determine depth
		depth := 0
		if cfg.depth > 0 {
			depth = cfg.depth
		} else if cfg.maxDepth == 0 {
			// Infer depth from regex pattern (number of slashes + 1)
			depth = countSlashes(regexPattern) + 1
		}

		var fileEntries []fileEntry
		var err error

		if cfg.maxDepth > 0 {
			fileEntries, err = listFilesUpToDepth(workDir, cfg.maxDepth)
		} else {
			fileEntries, err = listFilesAtDepth(workDir, depth)
		}

		if err != nil {
			fmt.Fprintf(os.Stderr, "[error] unable to read directory: %v\n", err)
			os.Exit(1)
		}

		entries, err := computeRegexRename(fileEntries, regexPattern, outputPattern, preserveExt, workDir, cfg.overwrite, cfg.testMode)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		renameEntries = entries

	} else if len(cfg.posArgs) == 1 {
		// Single positional arg - OUTPUT only, no SOURCE
		// This is treated as: "output only without source" which requires -r or -s to be set
		fmt.Fprintln(os.Stderr, "error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\nusage: run '"+appName+" --help' for more information.")
		os.Exit(1)
	} else {
		fmt.Fprintln(os.Stderr, "error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\nusage: run '"+appName+" --help' for more information.")
		os.Exit(1)
	}

	// Perform renames if not in test mode
	var successfulEntries []renameEntry
	if !cfg.testMode {
		successfulEntries = performRenames(renameEntries, workDir, cfg.mkdir, cfg.overwrite)
	} else {
		successfulEntries = renameEntries
	}

	// Print table (unless quiet)
	if !cfg.quiet {
		printTable(successfulEntries)
	}

	// Generate map file if requested
	if cfg.generate != "" {
		if err := generateMapFile(successfulEntries, cfg.generate); err != nil {
			fmt.Fprintf(os.Stderr, "[error] unable to write map file '%s': %v\n", cfg.generate, err)
			os.Exit(1)
		}
	}
}
