type appConfig struct {
	dir      string
	depth    int // 0 = not set
	maxDepth int // 0 = not set
	noExt    bool
	generate string
	mkdir    bool
	mapFile  string
	quiet    bool
	regex    string
	sortOrder string // "asc", "desc", ""
	testMode bool
	overwrite bool
	// positional args
	posArgs []string
}

func parseArgs(args []string) (*appConfig, error) {
	cfg := &appConfig{}

	i := 0
	for i < len(args) {
		arg := args[i]

		switch {
		case arg == "--help" || arg == "-h":
			if arg == "--help" {
				printUsage()
			} else {
				printShortUsage()
			}
			os.Exit(0)
		case arg == "--version" || arg == "-V":
			fmt.Printf("%s %s\n", appName, version)
			os.Exit(0)
		case arg == "-d" || arg == "--dir":
			i++
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: '%s'", arg)
			}
