// ===== Natural Sort =====

// naturalKey splits a string into segments of digits and non-digits
// for natural sorting
type naturalSegment struct {
	isNum bool
	num   int
	str   string
}

func splitNatural(s string) []naturalSegment {
	var segs []naturalSegment
	i := 0
	for i < len(s) {
		if unicode.IsDigit(rune(s[i])) {
			j := i
			for j < len(s) && unicode.IsDigit(rune(s[j])) {
				j++
			}
			n, _ := strconv.Atoi(s[i:j])
			segs = append(segs, naturalSegment{isNum: true, num: n, str: s[i:j]})
			i = j
		} else {
			j := i
			for j < len(s) && !unicode.IsDigit(rune(s[j])) {
				j++
			}
			segs = append(segs, naturalSegment{isNum: false, str: s[i:j]})
			i = j
		}
	}
	return segs
}

func naturalLess(a, b string) bool {
	segsA := splitNatural(a)
	segsB := splitNatural(b)
	for i := 0; i < len(segsA) && i < len(segsB); i++ {
		sa := segsA[i]
		sb := segsB[i]
		if sa.isNum && sb.isNum {
			if sa.num != sb.num {
				return sa.num < sb.num
			}
		} else if !sa.isNum && !sb.isNum {
			if sa.str != sb.str {
				return sa.str < sb.str
			}
		} else {
			// num vs non-num: num comes first
			return sa.isNum
		}
	}
	return len(segsA) < len(segsB)
}

// ===== Extension handling (Rust-compatible) =====
// Returns extension including dot, or "" if none
// Matches Rust's Path::extension() behavior:
// - Dotfiles like ".gitignore", ".env" -> no extension
// - ".hidden.txt" -> ".txt"
func rustExtension(filename string) string {
	// Get base name only
	base := filepath.Base(filename)
	// If starts with ".", strip it for analysis
	s := base
	if strings.HasPrefix(s, ".") {
		s = s[1:]
	}
	idx := strings.LastIndex(s, ".")
	if idx < 0 {
		return ""
	}
	return s[idx:]
}

// ===== Output Pattern Parsing =====

type placeholder struct {
	groupIndex int    // -1 means auto-increment
	padding    int    // 0 means no padding
	name       string // non-empty if named group
}

type outputToken struct {
	isPlaceholder bool
	text          string
	ph            placeholder
}

// parseOutputPattern parses the output pattern into tokens
// Supports: {G:P}, {G}, {:P}, {}, and escaped \{ \}
func parseOutputPattern(pattern string) ([]outputToken, error) {
	var tokens []outputToken
	i := 0
	for i < len(pattern) {
		if pattern[i] == '\\' && i+1 < len(pattern) {
			if pattern[i+1] == '{' || pattern[i+1] == '}' {
				tokens = append(tokens, outputToken{isPlaceholder: false, text: string(pattern[i+1])})
				i += 2
				continue
			}
			// Check for invalid escape
			tokens = append(tokens, outputToken{isPlaceholder: false, text: string(pattern[i])})
			i++
			continue
		}
		if pattern[i] == '{' {
			// Find matching }
			j := i + 1
			for j < len(pattern) && pattern[j] != '}' {
				j++
			}
			if j >= len(pattern) {
				return nil, fmt.Errorf("[output-format] unmatched '{' in pattern")
			}
			inner := pattern[i+1 : j]
			ph, err := parsePlaceholder(inner)
			if err != nil {
				return nil, err
			}
			tokens = append(tokens, outputToken{isPlaceholder: true, ph: ph})
			i = j + 1
			continue
		}
		if pattern[i] == '}' {
			return nil, fmt.Errorf("[output-format] unmatched '}' in pattern")
		}
		// Find next special character
		j := i + 1
		for j < len(pattern) && pattern[j] != '{' && pattern[j] != '}' && !(pattern[j] == '\\' && j+1 < len(pattern) && (pattern[j+1] == '{' || pattern[j+1] == '}')) {
			j++
		}
		tokens = append(tokens, outputToken{isPlaceholder: false, text: pattern[i:j]})
		i = j
	}
	return tokens, nil
}

func parsePlaceholder(inner string) (placeholder, error) {
	// inner can be: "", "G", ":P", "G:P", "name", "name:P"
	if inner == "" {
		return placeholder{groupIndex: -1, padding: 0}, nil
	}
	colonIdx := strings.Index(inner, ":")
	var groupPart, paddingPart string
	if colonIdx < 0 {
		groupPart = inner
		paddingPart = ""
	} else {
		groupPart = inner[:colonIdx]
		paddingPart = inner[colonIdx+1:]
	}

	ph := placeholder{groupIndex: -1}

	// Parse group part
	if groupPart == "" {
		ph.groupIndex = -1 // auto-increment
	} else if idx, err := strconv.Atoi(groupPart); err == nil {
		ph.groupIndex = idx
	} else {
		// Named group
		ph.name = groupPart
		ph.groupIndex = -2 // marker for named group
	}

	// Parse padding
	if paddingPart != "" {
		p, err := strconv.Atoi(paddingPart)
		if err != nil {
			return placeholder{}, fmt.Errorf("[output-format] invalid padding '%s'", paddingPart)
		}
		ph.padding = p
	}

	return ph, nil
}

// applyPattern applies the output pattern to a set of groups
// autoCounter is the current auto-increment counter (passed by reference via pointer)
// groups[0] = full match, groups[1..] = capture groups
// namedGroups = map of name -> value
func applyPattern(tokens []outputToken, groups []string, namedGroups map[string]string, autoCounter *int) string {
	var sb strings.Builder
	for _, tok := range tokens {
		if !tok.isPlaceholder {
			sb.WriteString(tok.text)
			continue
		}
		ph := tok.ph
		var value string

		if ph.groupIndex == -1 {
			// Auto-increment
			*autoCounter++
			idx := *autoCounter
			if idx < len(groups) {
				value = groups[idx]
			}
		} else if ph.groupIndex == -2 {
			// Named group
			value = namedGroups[ph.name]
		} else {
			// Explicit index
			if ph.groupIndex < len(groups) {
				value = groups[ph.groupIndex]
			}
		}

		// Apply padding
		if ph.padding > 0 {
			// Only pad positive numbers
			if n, err := strconv.Atoi(value); err == nil && n >= 0 {
				value = fmt.Sprintf("%0*d", ph.padding, n)
			}
		}

		sb.WriteString(value)
	}
	return sb.String()
}

// ===== File listing =====

type fileEntry struct {
	relPath string // relative path from working dir
	isDir   bool
}

// listFilesAtDepth lists files at exactly the specified depth (1 = current dir)
func listFilesAtDepth(dir string, depth int) ([]fileEntry, error) {
	if depth <= 0 {
		return nil, nil
	}

	var entries []fileEntry
	if depth == 1 {
		// List files in the current directory
		dirEntries, err := os.ReadDir(dir)
		if err != nil {
			return nil, err
		}
		for _, de := range dirEntries {
			entries = append(entries, fileEntry{relPath: de.Name(), isDir: de.IsDir()})
		}
		return entries, nil
	}

	// Need to go deeper
	dirEntries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	for _, de := range dirEntries {
		if de.IsDir() {
			subEntries, err := listFilesAtDepth(filepath.Join(dir, de.Name()), depth-1)
			if err != nil {
				continue
			}
			for _, se := range subEntries {
				entries = append(entries, fileEntry{
					relPath: de.Name() + "/" + se.relPath,
					isDir:   se.isDir,
				})
			}
		}
	}
	return entries, nil
}

// listFilesUpToDepth lists files from depth 1 to maxDepth
func listFilesUpToDepth(dir string, maxDepth int) ([]fileEntry, error) {
	var entries []fileEntry
	for d := 1; d <= maxDepth; d++ {
		es, err := listFilesAtDepth(dir, d)
		if err != nil {
			return nil, err
		}
		entries = append(entries, es...)
	}
	return entries, nil
}

// listCurrentDir lists files in the current directory only (depth 1)
func listCurrentDir(dir string) ([]fileEntry, error) {
	dirEntries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var entries []fileEntry
	for _, de := range dirEntries {
		entries = append(entries, fileEntry{relPath: de.Name(), isDir: de.IsDir()})
	}
	return entries, nil
}

// ===== Conflict resolution =====

// deduplicate output: if output already exists in existing or planned, prepend "_"
func deconflictOutput(output string, existing map[string]bool) string {
	dir := filepath.Dir(output)
	base := filepath.Base(output)
	for existing[output] {
		if dir == "." {
			base = "_" + base
			output = base
		} else {
			base = "_" + base
			output = dir + "/" + base
		}
	}
	return output
}

// ===== Main rename logic =====

type renameEntry struct {
	input  string
	output string
}

// computeSortRename computes rename map for sort mode
func computeSortRename(entries []fileEntry, outputPattern string, sortAsc bool, preserveExt bool, workDir string, overwrite bool, testMode bool) ([]renameEntry, error) {
	// Sort entries naturally
	fileList := make([]string, len(entries))
	for i, e := range entries {
		fileList[i] = e.relPath
	}
	sort.Slice(fileList, func(i, j int) bool {
		if sortAsc {
			return naturalLess(fileList[i], fileList[j])
		}
		return naturalLess(fileList[j], fileList[i])
	})

	// Parse output pattern
	tokens, err := parseOutputPattern(outputPattern)
	if err != nil {
		return nil, err
	}

	// Build claimed set (existing files on disk)
	claimed := make(map[string]bool)
	if !overwrite {
		// Add all existing files to claimed set
		for _, f := range fileList {
			claimed[f] = true
		}
	}

	var result []renameEntry
	counter := 0
	for _, relPath := range fileList {
		// Build groups for this file
		// group 0 = full filename, group 1 = counter
		counter++
		ext := rustExtension(filepath.Base(relPath))
		baseNameWithExt := filepath.Base(relPath)

		groups := []string{baseNameWithExt, strconv.Itoa(counter)}
		namedGroups := map[string]string{}

		autoCounter := 0
		outputBase := applyPattern(tokens, groups, namedGroups, &autoCounter)

		// Preserve extension
		if preserveExt && ext != "" {
			outputBase = outputBase + ext
		}

		// Handle directory prefix if relPath has dirs
		dir := filepath.Dir(relPath)
		var fullOutput string
		if dir == "." {
			fullOutput = outputBase
		} else {
			fullOutput = dir + "/" + outputBase
		}

		// Deconflict
		if !overwrite {
			fullOutput = deconflictOutput(fullOutput, claimed)
			if !testMode {
				claimed[fullOutput] = true
			}
		}

		result = append(result, renameEntry{input: relPath, output: fullOutput})
	}

	return result, nil
}

// computeRegexRename computes rename map for regex mode  
func computeRegexRename(entries []fileEntry, regexPattern string, outputPattern string, preserveExt bool, workDir string, overwrite bool, testMode bool) ([]renameEntry, error) {
	re, err := regexp.Compile(regexPattern)
	if err != nil {
		return nil, fmt.Errorf("[error] invalid regex: %v", err)
	}

	tokens, err := parseOutputPattern(outputPattern)
	if err != nil {
		return nil, err
	}

	// Get named group names from regex
	groupNames := re.SubexpNames()

	// Build claimed set
	claimed := make(map[string]bool)
	if !overwrite {
		// Add all existing files in the directory to claimed set
		// We need to scan ALL files, not just the ones being processed
		dirEntries, _ := os.ReadDir(workDir)
		for _, de := range dirEntries {
			claimed[de.Name()] = true
		}
	}

	// Sort entries alphabetically (for consistent output)
	fileList := make([]string, len(entries))
	for i, e := range entries {
		fileList[i] = e.relPath
	}
	sort.Strings(fileList)

	var result []renameEntry
	for _, relPath := range fileList {
		match := re.FindStringSubmatch(relPath)
		if match == nil {
			continue
		}

		// Build groups
		groups := match // groups[0] = full match, groups[1..] = captured

		// Build named groups map
		namedGroups := make(map[string]string)
		for i, name := range groupNames {
			if name != "" && i < len(match) {
				namedGroups[name] = match[i]
			}
		}

		// Apply pattern
		autoCounter := 0
		outputBase := applyPattern(tokens, groups, namedGroups, &autoCounter)

		// Get extension from the actual FILE (not the regex match)
		ext := rustExtension(filepath.Base(relPath))
		if preserveExt && ext != "" {
			outputBase = outputBase + ext
		}

		// Deconflict
		if !overwrite {
			outputBase = deconflictOutput(outputBase, claimed)
			if !testMode {
				claimed[outputBase] = true
			}
		}

		result = append(result, renameEntry{input: relPath, output: outputBase})
	}

	return result, nil
}

// computeMapRename computes rename map from JSON map file
func computeMapRename(mapPath string, overwrite bool, testMode bool) ([]renameEntry, error) {
	data, err := os.ReadFile(mapPath)
	if err != nil {
		return nil, fmt.Errorf("[error] unable to read map file '%s': %v", mapPath, err)
	}

	// Parse JSON: keys are inputs, values are outputs
	var jsonMap map[string]string
	if err := json.Unmarshal(data, &jsonMap); err != nil {
		return nil, fmt.Errorf("[error] invalid JSON map file: %v", err)
	}

	// Build claimed set (existing files on disk)
	claimed := make(map[string]bool)
	if !overwrite {
		// We need to know what files exist in the directory
		// Use current working directory
		dirEntries, _ := os.ReadDir(".")
		for _, de := range dirEntries {
			claimed[de.Name()] = true
		}
	}

	// Process entries in map order (Go maps are random order)
	var result []renameEntry
	for input, output := range jsonMap {
		// Deconflict
		if !overwrite {
			output = deconflictOutput(output, claimed)
			if !testMode {
				claimed[output] = true
			}
		}
		result = append(result, renameEntry{input: input, output: output})
	}

	return result, nil
}

// ===== Table printing =====

func printTable(entries []renameEntry) {
	if len(entries) == 0 {
		return
	}

	// Find max widths
	inputHeader := "Input"
	outputHeader := "Output"
	maxInput := len(inputHeader)
	maxOutput := len(outputHeader)
	for _, e := range entries {
		if len(e.input) > maxInput {
			maxInput = len(e.input)
		}
		if len(e.output) > maxOutput {
			maxOutput = len(e.output)
		}
	}

	sep := fmt.Sprintf("+%s+%s+",
		strings.Repeat("-", maxInput+2),
		strings.Repeat("-", maxOutput+2))

	fmt.Println(sep)
	fmt.Printf("| %-*s | %-*s |\n", maxInput, inputHeader, maxOutput, outputHeader)
	fmt.Println(sep)
	for _, e := range entries {
		fmt.Printf("| %-*s | %-*s |\n", maxInput, e.input, maxOutput, e.output)
	}
	fmt.Println(sep)
}

// ===== Generate map file =====

func generateMapFile(entries []renameEntry, path string) error {
	// Build reverse map: output -> input (for undo)
	m := make(map[string]string)
	for _, e := range entries {
		m[e.output] = e.input
	}

	data, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return err
	}

	return os.WriteFile(path, data, 0644)
}

// ===== Actual file renaming =====

func performRenames(entries []renameEntry, workDir string, mkdir bool, overwrite bool) []renameEntry {
	var successful []renameEntry
	for _, e := range entries {
		src := filepath.Join(workDir, filepath.FromSlash(e.input))
		dst := filepath.Join(workDir, filepath.FromSlash(e.output))

		if mkdir {
			os.MkdirAll(filepath.Dir(dst), 0755)
		}

		err := os.Rename(src, dst)
		if err != nil {
			fmt.Fprintf(os.Stderr, "[error] unable to rename '%s': %v\n", e.input, err)
		} else {
			successful = append(successful, e)
		}
	}
	return successful
}

// ===== Count path separators in a pattern =====
func countSlashes(s string) int {
	return strings.Count(s, "/")
}

