func main() {
	cfg, showHelp, showShortHelp := parseArgs(os.Args[1:])

	if showHelp {
		printUsageLong()
		os.Exit(0)
	}
	if showShortHelp {
		printUsageShort()
		os.Exit(0)
	}

	if cfg.dir != "" {
		if err := os.Chdir(cfg.dir); err != nil {
			fmt.Fprintf(os.Stderr, "[error] unable to change directory to '%s': %v\n", cfg.dir, err)
			os.Exit(1)
		}
	}

	preserveExt := !cfg.noExt
	var renameEntries []renameEntry

	if cfg.mapFile != "" {
		// Map mode
		entries, err := computeMapRename(cfg.mapFile, cfg.overwrite, cfg.testMode)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		renameEntries = entries

	} else if cfg.sortOrder != "" {
		// Sort mode
		var outputPattern string
		if len(cfg.posArgs) >= 2 {
			outputPattern = cfg.posArgs[len(cfg.posArgs)-1]
			if cfg.regex == "" {
				cfg.regex = cfg.posArgs[len(cfg.posArgs)-2]
			}
		} else if len(cfg.posArgs) == 1 {
			outputPattern = cfg.posArgs[0]
		} else {
			fmt.Fprintf(os.Stderr, "error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\nusage: run '%s --help' for more information.\n", appName)
			os.Exit(1)
		}

		dirEntries, err := os.ReadDir(".")
		if err != nil {
			fmt.Fprintf(os.Stderr, "[error] unable to read directory: %v\n", err)
			os.Exit(1)
		}
		var allEntries []fileEntry
		for _, de := range dirEntries {
			allEntries = append(allEntries, fileEntry{relPath: de.Name()})
		}

		var filteredEntries []fileEntry
		if cfg.regex != "" {
			re, err := regexp.Compile(cfg.regex)
			if err != nil {
				fmt.Fprintf(os.Stderr, "[error] invalid regex: %v\n", err)
				os.Exit(1)
			}
			for _, e := range allEntries {
				if re.MatchString(e.relPath) {
					filteredEntries = append(filteredEntries, e)
				}
			}
		} else {
			filteredEntries = allEntries
		}

		entries, err := computeSortRename(filteredEntries, outputPattern, cfg.sortOrder == "asc", preserveExt, cfg.overwrite, cfg.testMode)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		renameEntries = entries

	} else if cfg.regex != "" || len(cfg.posArgs) >= 2 {
		// Regex mode
		var regexPattern, outputPattern string
		if len(cfg.posArgs) >= 2 {
			outputPattern = cfg.posArgs[len(cfg.posArgs)-1]
			if cfg.regex == "" {
				regexPattern = cfg.posArgs[len(cfg.posArgs)-2]
			} else {
				regexPattern = cfg.regex
			}
		} else {
			regexPattern = cfg.regex
			if len(cfg.posArgs) == 1 {
				outputPattern = cfg.posArgs[0]
			} else {
				fmt.Fprintf(os.Stderr, "error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\nusage: run '%s --help' for more information.\n", appName)
				os.Exit(1)
			}
		}

		var fileEntries []fileEntry
		var err error
		if cfg.maxDepth > 0 {
			fileEntries, err = listFilesUpToDepth(".", cfg.maxDepth)
		} else {
			depth := cfg.depth
			if depth == 0 {
				depth = countSlashes(regexPattern) + 1
			}
			fileEntries, err = listFilesAtDepth(".", depth)
		}
		if err != nil {
			fmt.Fprintf(os.Stderr, "[error] unable to read directory: %v\n", err)
			os.Exit(1)
		}

		entries, err := computeRegexRename(fileEntries, regexPattern, outputPattern, preserveExt, cfg.overwrite, cfg.testMode)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		renameEntries = entries

	} else {
		fmt.Fprintf(os.Stderr, "error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\nusage: run '%s --help' for more information.\n", appName)
		os.Exit(1)
	}

	var successfulEntries []renameEntry
	if !cfg.testMode {
		successfulEntries = performRenames(renameEntries, cfg.mkdir)
	} else {
		successfulEntries = renameEntries
	}

	if !cfg.quiet {
		printTable(successfulEntries)
	}

	if cfg.generate != "" {
		if err := generateMapFile(successfulEntries, cfg.generate); err != nil {
			fmt.Fprintf(os.Stderr, "[error] unable to write map file '%s': %v\n", cfg.generate, err)
			os.Exit(1)
		}
	}
}

