// ===== Natural Sort =====

func naturalLess(a, b string) bool {
	for len(a) > 0 && len(b) > 0 {
		aDigit := a[0] >= '0' && a[0] <= '9'
		bDigit := b[0] >= '0' && b[0] <= '9'
		if aDigit && bDigit {
			ai := 0
			for ai < len(a) && a[ai] >= '0' && a[ai] <= '9' {
				ai++
			}
			bi := 0
			for bi < len(b) && b[bi] >= '0' && b[bi] <= '9' {
				bi++
			}
			aNum, _ := strconv.Atoi(a[:ai])
			bNum, _ := strconv.Atoi(b[:bi])
			if aNum != bNum {
				return aNum < bNum
			}
			a = a[ai:]
			b = b[bi:]
		} else if !aDigit && !bDigit {
			if a[0] != b[0] {
				return a[0] < b[0]
			}
			a = a[1:]
			b = b[1:]
		} else {
			return aDigit
		}
	}
	return len(a) < len(b)
}

// ===== Extension handling (Rust-compatible) =====

func rustExtension(filename string) string {
	base := filepath.Base(filename)
	s := base
	if strings.HasPrefix(s, ".") {
		s = s[1:]
	}
	idx := strings.LastIndex(s, ".")
	if idx < 0 {
		return ""
	}
	return s[idx:]
}

// ===== Output Pattern Parsing =====

type outputToken struct {
	isPlaceholder bool
	text          string
	groupIndex    int
	padding       int
	name          string
}

func parseOutputPattern(pattern string) ([]outputToken, error) {
	var tokens []outputToken
	i := 0
	for i < len(pattern) {
		if pattern[i] == '\\' && i+1 < len(pattern) {
			next := pattern[i+1]
			if next == '{' || next == '}' {
				tokens = append(tokens, outputToken{isPlaceholder: false, text: string(next)})
				i += 2
				continue
			}
			return nil, fmt.Errorf("[output-format] invalid escape character of '%c' at '%d'", next, i+1)
		}
		if pattern[i] == '{' {
			j := i + 1
			for j < len(pattern) && pattern[j] != '}' {
				j++
			}
			if j >= len(pattern) {
				return nil, fmt.Errorf("[output-format] unmatched '{' in pattern")
			}
			inner := pattern[i+1 : j]
			tok, err := parsePlaceholderToken(inner)
			if err != nil {
				return nil, err
			}
			tokens = append(tokens, tok)
			i = j + 1
			continue
		}
		if pattern[i] == '}' {
			return nil, fmt.Errorf("[output-format] unmatched '}' in pattern")
		}
		j := i + 1
		for j < len(pattern) {
			if pattern[j] == '{' || pattern[j] == '}' {
				break
			}
			if pattern[j] == '\\' && j+1 < len(pattern) && (pattern[j+1] == '{' || pattern[j+1] == '}') {
				break
			}
			j++
		}
		tokens = append(tokens, outputToken{isPlaceholder: false, text: pattern[i:j]})
		i = j
	}
	return tokens, nil
}

func parsePlaceholderToken(inner string) (outputToken, error) {
	tok := outputToken{isPlaceholder: true, groupIndex: -1}
	if inner == "" {
		return tok, nil
	}
	colonIdx := strings.Index(inner, ":")
	var groupPart, paddingPart string
	if colonIdx < 0 {
		groupPart = inner
	} else {
		groupPart = inner[:colonIdx]
		paddingPart = inner[colonIdx+1:]
	}
	if groupPart == "" {
		tok.groupIndex = -1
	} else if idx, err := strconv.Atoi(groupPart); err == nil {
		tok.groupIndex = idx
	} else {
		tok.name = groupPart
		tok.groupIndex = -2
	}
	if paddingPart != "" {
		p, err := strconv.Atoi(paddingPart)
		if err != nil {
			return tok, fmt.Errorf("[output-format] invalid padding '%s'", paddingPart)
		}
		tok.padding = p
	}
	return tok, nil
}

func applyPattern(tokens []outputToken, groups []string, namedGroups map[string]string, autoCounter *int) string {
	var sb strings.Builder
	for _, tok := range tokens {
		if !tok.isPlaceholder {
			sb.WriteString(tok.text)
			continue
		}
		var value string
		switch tok.groupIndex {
		case -1:
			*autoCounter++
			idx := *autoCounter
			if idx < len(groups) {
				value = groups[idx]
			}
		case -2:
			value = namedGroups[tok.name]
		default:
			if tok.groupIndex < len(groups) {
				value = groups[tok.groupIndex]
			}
		}
		if tok.padding > 0 {
			if n, err := strconv.Atoi(value); err == nil && n >= 0 {
				value = fmt.Sprintf("%0*d", tok.padding, n)
			}
		}
		sb.WriteString(value)
	}
	return sb.String()
}

// ===== File listing =====

type fileEntry struct {
	relPath string
}

func listFilesAtDepth(dir string, depth int) ([]fileEntry, error) {
	if depth <= 0 {
		return nil, nil
	}
	if depth == 1 {
		dirEntries, err := os.ReadDir(dir)
		if err != nil {
			return nil, err
		}
		var entries []fileEntry
		for _, de := range dirEntries {
			entries = append(entries, fileEntry{relPath: de.Name()})
		}
		return entries, nil
	}
	dirEntries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var entries []fileEntry
	for _, de := range dirEntries {
		if de.IsDir() {
			subEntries, err := listFilesAtDepth(filepath.Join(dir, de.Name()), depth-1)
			if err != nil {
				continue
			}
			for _, se := range subEntries {
				entries = append(entries, fileEntry{relPath: de.Name() + "/" + se.relPath})
			}
		}
	}
	return entries, nil
}

func listFilesUpToDepth(dir string, maxDepth int) ([]fileEntry, error) {
	var entries []fileEntry
	for d := 1; d <= maxDepth; d++ {
		es, err := listFilesAtDepth(dir, d)
		if err != nil {
			return nil, err
		}
		entries = append(entries, es...)
	}
	return entries, nil
}

// ===== Conflict resolution =====

func deconflictOutput(output string, claimed map[string]bool) string {
	dir := filepath.Dir(output)
	base := filepath.Base(output)
	for claimed[output] {
		if dir == "." {
			base = "_" + base
			output = base
		} else {
			base = "_" + base
			output = dir + "/" + base
		}
	}
	return output
}

// ===== Rename entries =====

type renameEntry struct {
	input      string
	output     string
	conflicted bool // true if output was deconflicted (got _ prefix)
}

func buildClaimedFromDisk(dir string) map[string]bool {
	claimed := make(map[string]bool)
	dirEntries, _ := os.ReadDir(dir)
	for _, de := range dirEntries {
		claimed[de.Name()] = true
	}
	return claimed
}

// ===== Sort mode =====

func computeSortRename(
	entries []fileEntry,
	outputPattern string,
	sortAsc bool,
	preserveExt bool,
	overwrite bool,
	testMode bool,
) ([]renameEntry, error) {
	fileList := make([]string, len(entries))
	for i, e := range entries {
		fileList[i] = e.relPath
	}
	sort.Slice(fileList, func(i, j int) bool {
		if sortAsc {
			return naturalLess(fileList[i], fileList[j])
		}
		return naturalLess(fileList[j], fileList[i])
	})

	tokens, err := parseOutputPattern(outputPattern)
	if err != nil {
		return nil, err
	}

	// In sort mode, group 0 = filename, group 1 = counter
	computeOutputFn := func(relPath string, counter int) string {
		ext := rustExtension(filepath.Base(relPath))
		baseNameWithExt := filepath.Base(relPath)
		groups := []string{baseNameWithExt, strconv.Itoa(counter)}
		namedGroups := map[string]string{}
		autoCounter := 0
		out := applyPattern(tokens, groups, namedGroups, &autoCounter)
		if preserveExt && ext != "" {
			out = out + ext
		}
		dir := filepath.Dir(relPath)
		if dir != "." {
			out = dir + "/" + out
		}
		return out
	}

	return processSortedFiles(fileList, computeOutputFn, overwrite, testMode)
}

// processSortedFiles handles the rename computation for sort mode.
// Table output order: non-conflicting entries first (in sort order), conflicting last (in sort order)
func processSortedFiles(
	sortedFiles []string,
	computeOutput func(relPath string, counter int) string,
	overwrite bool,
	testMode bool,
) ([]renameEntry, error) {
	claimed := buildClaimedFromDisk(".")

	if overwrite {
		// No conflict detection, dedup by output (last wins)
		outMap := make(map[string]renameEntry)
		var outOrder []string
		for counter, relPath := range sortedFiles {
			out := computeOutput(relPath, counter+1)
			if out == "" {
				continue
			}
			if _, exists := outMap[out]; !exists {
				outOrder = append(outOrder, out)
			}
			outMap[out] = renameEntry{input: relPath, output: out}
		}
		var result []renameEntry
		for _, out := range outOrder {
			result = append(result, outMap[out])
		}
		return result, nil
	}

	// Real or test mode: build pairs with conflict detection
	type pair struct {
		input      string
		rawOutput  string
		finalOutput string
		conflicted bool
		sortIdx    int
	}

	var pairs []pair
	plannedClaimed := make(map[string]bool) // Only used in real mode

	for counter, relPath := range sortedFiles {
		out := computeOutput(relPath, counter+1)
		if out == "" {
			continue
		}
		rawOut := out
		isSelf := (out == relPath)

		if !isSelf {
			if testMode {
				// Test mode: check only disk files
				out = deconflictOutput(out, claimed)
			} else {
				// Real mode: check disk + planned
				combined := make(map[string]bool)
				for k, v := range claimed {
					combined[k] = v
				}
				for k, v := range plannedClaimed {
					combined[k] = v
				}
				out = deconflictOutput(out, combined)
				plannedClaimed[out] = true
			}
		}

		conflicted := (out != rawOut)
		pairs = append(pairs, pair{
			input:       relPath,
			rawOutput:   rawOut,
			finalOutput: out,
			conflicted:  conflicted,
			sortIdx:     counter,
		})
	}

	if testMode {
		// Dedup by final output: last wins (preserving original insertion order of key)
		type slot struct {
			input      string
			conflicted bool
			insertOrder int
		}
		outMap := make(map[string]*slot)
		insertOrder := 0
		for _, p := range pairs {
			isSelf := (p.input == p.finalOutput)
			if existing, ok := outMap[p.finalOutput]; ok {
				if !existing.conflicted || isSelf {
					// For self-renames: never overwrite
					// For non-self: overwrite but preserve insertion order
					if !isSelf {
						outMap[p.finalOutput] = &slot{input: p.input, conflicted: p.conflicted, insertOrder: existing.insertOrder}
					}
				}
			} else {
				outMap[p.finalOutput] = &slot{input: p.input, conflicted: p.conflicted, insertOrder: insertOrder}
				insertOrder++
			}
		}

		// Collect entries
		type indexedRename struct {
			re         renameEntry
			insertOrder int
		}
		var indexed []indexedRename
		for out, sl := range outMap {
			indexed = append(indexed, indexedRename{
				re:          renameEntry{input: sl.input, output: out, conflicted: sl.conflicted},
				insertOrder: sl.insertOrder,
			})
		}
		sort.Slice(indexed, func(i, j int) bool {
			return indexed[i].insertOrder < indexed[j].insertOrder
		})

		// Now order: non-conflicting first (in sort order), conflicting last (in sort order)
		var nonConflicted, conflicted []renameEntry
		for _, ie := range indexed {
			if ie.re.conflicted {
				conflicted = append(conflicted, ie.re)
			} else {
				nonConflicted = append(nonConflicted, ie.re)
			}
		}
		// Sort each group by INPUT using natural sort
		sort.Slice(nonConflicted, func(i, j int) bool {
			return naturalLess(nonConflicted[i].input, nonConflicted[j].input)
		})
		sort.Slice(conflicted, func(i, j int) bool {
			return naturalLess(conflicted[i].input, conflicted[j].input)
		})
		// But we need sort-mode ORDER which is sortAsc/sortDesc - hmm
		// We lost the sort direction info here...
		// Let me restructure

		return append(nonConflicted, conflicted...), nil
	}

	// Real mode: all entries, split into non-conflicting/conflicting groups
	var nonConflicted, conflicted []renameEntry
	for _, p := range pairs {
		re := renameEntry{input: p.input, output: p.finalOutput, conflicted: p.conflicted}
		if p.conflicted {
			conflicted = append(conflicted, re)
		} else {
			nonConflicted = append(nonConflicted, re)
		}
	}
	return append(nonConflicted, conflicted...), nil
}

// ===== Regex mode =====

func computeRegexRename(
	entries []fileEntry,
	regexPattern string,
	outputPattern string,
	preserveExt bool,
	overwrite bool,
	testMode bool,
) ([]renameEntry, error) {
	re, err := regexp.Compile(regexPattern)
	if err != nil {
		return nil, fmt.Errorf("[error] invalid regex: %v", err)
	}

	tokens, err := parseOutputPattern(outputPattern)
	if err != nil {
		return nil, err
	}

	groupNames := re.SubexpNames()

	fileList := make([]string, len(entries))
	for i, e := range entries {
		fileList[i] = e.relPath
	}
	sort.Slice(fileList, func(i, j int) bool {
		return naturalLess(fileList[i], fileList[j])
	})

	claimed := buildClaimedFromDisk(".")
	// Also add all scanned files as claimed
	for _, f := range fileList {
		claimed[f] = true
	}

	if overwrite {
		// No conflict resolution
		outMap := make(map[string]renameEntry)
		var outOrder []string
		for _, relPath := range fileList {
			match := re.FindStringSubmatch(relPath)
			if match == nil {
				continue
			}
			namedGroups := make(map[string]string)
			for i, name := range groupNames {
				if name != "" && i < len(match) {
					namedGroups[name] = match[i]
				}
			}
			autoCounter := 0
			out := applyPattern(tokens, match, namedGroups, &autoCounter)
			ext := rustExtension(filepath.Base(relPath))
			if preserveExt && ext != "" {
				out = out + ext
			}
			if _, exists := outMap[out]; !exists {
				outOrder = append(outOrder, out)
			}
			outMap[out] = renameEntry{input: relPath, output: out}
		}
		var result []renameEntry
		for _, out := range outOrder {
			result = append(result, outMap[out])
		}
		return result, nil
	}

	// Build rename list with conflict detection
	type pair struct {
		input      string
		rawOutput  string
		finalOutput string
		conflicted bool
	}

	var pairs []pair
	plannedClaimed := make(map[string]bool)

	for _, relPath := range fileList {
		match := re.FindStringSubmatch(relPath)
		if match == nil {
			continue
		}
		namedGroups := make(map[string]string)
		for i, name := range groupNames {
			if name != "" && i < len(match) {
				namedGroups[name] = match[i]
			}
		}
		autoCounter := 0
		out := applyPattern(tokens, match, namedGroups, &autoCounter)
		ext := rustExtension(filepath.Base(relPath))
		if preserveExt && ext != "" {
			out = out + ext
		}
		rawOut := out
		isSelf := (out == relPath)

		if !isSelf {
			if testMode {
				out = deconflictOutput(out, claimed)
			} else {
				combined := make(map[string]bool)
				for k, v := range claimed {
					combined[k] = v
				}
				for k, v := range plannedClaimed {
					combined[k] = v
				}
				out = deconflictOutput(out, combined)
				plannedClaimed[out] = true
			}
		}

		conflicted := (out != rawOut)
		pairs = append(pairs, pair{input: relPath, rawOutput: rawOut, finalOutput: out, conflicted: conflicted})
	}

	if testMode {
		// Dedup by final output in test mode
		type slot struct {
			input      string
			conflicted bool
			isSelf     bool
			insertOrder int
		}
		outMap := make(map[string]*slot)
		insertOrder := 0
		for _, p := range pairs {
			isSelf := (p.input == p.finalOutput)
			if existing, ok := outMap[p.finalOutput]; ok {
				if !existing.isSelf {
					// Overwrite non-self, preserve insertion order
					outMap[p.finalOutput] = &slot{
						input: p.input, conflicted: p.conflicted, isSelf: isSelf,
						insertOrder: existing.insertOrder,
					}
				}
			} else {
				outMap[p.finalOutput] = &slot{
					input: p.input, conflicted: p.conflicted, isSelf: isSelf,
					insertOrder: insertOrder,
				}
				insertOrder++
			}
		}

		// Collect and sort
		var conflictedList, nonConflictedList []renameEntry
		for out, sl := range outMap {
			re := renameEntry{input: sl.input, output: out, conflicted: sl.conflicted}
			if sl.conflicted {
				conflictedList = append(conflictedList, re)
			} else {
				nonConflictedList = append(nonConflictedList, re)
			}
		}
		// Sort each group by INPUT (natural sort)
		sort.Slice(conflictedList, func(i, j int) bool {
			return naturalLess(conflictedList[i].input, conflictedList[j].input)
		})
		sort.Slice(nonConflictedList, func(i, j int) bool {
			return naturalLess(nonConflictedList[i].input, nonConflictedList[j].input)
		})
		// Regex mode: conflicting FIRST
		return append(conflictedList, nonConflictedList...), nil
	}

	// Real mode: split into conflicting/non-conflicting groups
	var conflictedList, nonConflictedList []renameEntry
	for _, p := range pairs {
		re := renameEntry{input: p.input, output: p.finalOutput, conflicted: p.conflicted}
		if p.conflicted {
			conflictedList = append(conflictedList, re)
		} else {
			nonConflictedList = append(nonConflictedList, re)
		}
	}
	// Regex mode real: conflicting FIRST (for correct rename order)
	sort.Slice(conflictedList, func(i, j int) bool {
		return naturalLess(conflictedList[i].input, conflictedList[j].input)
	})
	sort.Slice(nonConflictedList, func(i, j int) bool {
		return naturalLess(nonConflictedList[i].input, nonConflictedList[j].input)
	})
	return append(conflictedList, nonConflictedList...), nil
}

// ===== Map mode =====

func computeMapRename(mapPath string, overwrite bool, testMode bool) ([]renameEntry, error) {
	data, err := os.ReadFile(mapPath)
	if err != nil {
		return nil, fmt.Errorf("[error] unable to read map file '%s': %v", mapPath, err)
	}

	var jsonMap map[string]string
	if err := json.Unmarshal(data, &jsonMap); err != nil {
		return nil, fmt.Errorf("[error] invalid JSON map file: %v", err)
	}

	claimed := buildClaimedFromDisk(".")

	if overwrite {
		var result []renameEntry
		for input, output := range jsonMap {
			result = append(result, renameEntry{input: input, output: output})
		}
		return result, nil
	}

	type pair struct {
		input      string
		rawOutput  string
		finalOutput string
		conflicted bool
	}

	var pairs []pair
	plannedClaimed := make(map[string]bool)

	for input, output := range jsonMap {
		rawOut := output
		isSelf := (output == input)
		if !isSelf {
			if testMode {
				output = deconflictOutput(output, claimed)
			} else {
				combined := make(map[string]bool)
				for k, v := range claimed {
					combined[k] = v
				}
				for k, v := range plannedClaimed {
					combined[k] = v
				}
				output = deconflictOutput(output, combined)
				plannedClaimed[output] = true
			}
		}
		conflicted := (output != rawOut)
		pairs = append(pairs, pair{input: input, rawOutput: rawOut, finalOutput: output, conflicted: conflicted})
	}

	if testMode {
		// Dedup by output, conflicting first then non-conflicting, each in natural sort
		type slot struct {
			input      string
			conflicted bool
			isSelf     bool
			insertOrder int
		}
		outMap := make(map[string]*slot)
		insertOrder := 0
		for _, p := range pairs {
			isSelf := (p.input == p.finalOutput)
			if existing, ok := outMap[p.finalOutput]; ok {
				if !existing.isSelf {
					outMap[p.finalOutput] = &slot{
						input: p.input, conflicted: p.conflicted, isSelf: isSelf,
						insertOrder: existing.insertOrder,
					}
				}
			} else {
				outMap[p.finalOutput] = &slot{
					input: p.input, conflicted: p.conflicted, isSelf: isSelf,
					insertOrder: insertOrder,
				}
				insertOrder++
			}
		}

		var conflictedList, nonConflictedList []renameEntry
		for out, sl := range outMap {
			re := renameEntry{input: sl.input, output: out, conflicted: sl.conflicted}
			if sl.conflicted {
				conflictedList = append(conflictedList, re)
			} else {
				nonConflictedList = append(nonConflictedList, re)
			}
		}
		sort.Slice(conflictedList, func(i, j int) bool {
			return naturalLess(conflictedList[i].input, conflictedList[j].input)
		})
		sort.Slice(nonConflictedList, func(i, j int) bool {
			return naturalLess(nonConflictedList[i].input, nonConflictedList[j].input)
		})
		return append(conflictedList, nonConflictedList...), nil
	}

	// Real mode
	var conflictedList, nonConflictedList []renameEntry
	for _, p := range pairs {
		re := renameEntry{input: p.input, output: p.finalOutput, conflicted: p.conflicted}
		if p.conflicted {
			conflictedList = append(conflictedList, re)
		} else {
			nonConflictedList = append(nonConflictedList, re)
		}
	}
	sort.Slice(conflictedList, func(i, j int) bool {
		return naturalLess(conflictedList[i].input, conflictedList[j].input)
	})
	sort.Slice(nonConflictedList, func(i, j int) bool {
		return naturalLess(nonConflictedList[i].input, nonConflictedList[j].input)
	})
	return append(conflictedList, nonConflictedList...), nil
}

// ===== Table printing =====

func printTable(entries []renameEntry) {
	if len(entries) == 0 {
		return
	}
	inputHeader := "Input"
	outputHeader := "Output"
	maxInput := len(inputHeader)
	maxOutput := len(outputHeader)
	for _, e := range entries {
		if len(e.input) > maxInput {
			maxInput = len(e.input)
		}
		if len(e.output) > maxOutput {
			maxOutput = len(e.output)
		}
	}
	sep := fmt.Sprintf("+%s+%s+",
		strings.Repeat("-", maxInput+2),
		strings.Repeat("-", maxOutput+2))
	fmt.Println(sep)
	fmt.Printf("| %-*s | %-*s |\n", maxInput, inputHeader, maxOutput, outputHeader)
	fmt.Println(sep)
	for _, e := range entries {
		fmt.Printf("| %-*s | %-*s |\n", maxInput, e.input, maxOutput, e.output)
	}
	fmt.Println(sep)
}

// ===== Generate map file =====

func generateMapFile(entries []renameEntry, path string) error {
	type kv struct{ k, v string }
	var pairs []kv
	seen := make(map[string]bool)
	for _, e := range entries {
		if !seen[e.output] {
			pairs = append(pairs, kv{e.output, e.input})
			seen[e.output] = true
		}
	}
	var sb strings.Builder
	sb.WriteString("{\n")
	for i, p := range pairs {
		kJSON, _ := json.Marshal(p.k)
		vJSON, _ := json.Marshal(p.v)
		sb.WriteString(fmt.Sprintf("  %s: %s", kJSON, vJSON))
		if i < len(pairs)-1 {
			sb.WriteString(",")
		}
		sb.WriteString("\n")
	}
	sb.WriteString("}")
	return os.WriteFile(path, []byte(sb.String()), 0644)
}

// ===== Actual file renaming =====

func performRenames(entries []renameEntry, mkdir bool) []renameEntry {
	var successful []renameEntry
	for _, e := range entries {
		src := filepath.FromSlash(e.input)
		dst := filepath.FromSlash(e.output)
		if mkdir {
			os.MkdirAll(filepath.Dir(dst), 0755)
		}
		err := os.Rename(src, dst)
		if err != nil {
			fmt.Fprintf(os.Stderr, "[error] unable to rename '%s': %v\n", e.input, err)
		} else {
			successful = append(successful, e)
		}
	}
	return successful
}

func countSlashes(s string) int {
	return strings.Count(s, "/")
}

// ===== CLI =====

type appConfig struct {
	dir       string
	depth     int
	maxDepth  int
	noExt     bool
	generate  string
	mkdir     bool
	mapFile   string
	quiet     bool
	regex     string
	sortOrder string
	testMode  bool
	overwrite bool
	posArgs   []string
}

func parseArgs(args []string) (*appConfig, bool, bool) {
	cfg := &appConfig{}
	i := 0
	for i < len(args) {
		arg := args[i]
		switch {
		case arg == "--help":
			return cfg, true, false
		case arg == "-h":
			return cfg, false, true
		case arg == "--version" || arg == "-V":
			fmt.Printf("%s %s\n", appName, version)
			os.Exit(0)
		case arg == "-d" || arg == "--dir":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: a value is required for '--dir <PATH>' but none was supplied\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			cfg.dir = args[i]
		case strings.HasPrefix(arg, "--dir="):
			cfg.dir = arg[6:]
		case arg == "--depth":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: a value is required for '--depth <DEPTH>' but none was supplied\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			n, err := strconv.Atoi(args[i])
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: invalid digit found in string\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			cfg.depth = n
		case strings.HasPrefix(arg, "--depth="):
			n, err := strconv.Atoi(arg[8:])
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: invalid digit found in string\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			cfg.depth = n
		case arg == "--max-depth":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: a value is required for '--max-depth <DEPTH>' but none was supplied\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			n, err := strconv.Atoi(args[i])
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: invalid digit found in string\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			cfg.maxDepth = n
		case strings.HasPrefix(arg, "--max-depth="):
			n, err := strconv.Atoi(arg[12:])
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: invalid digit found in string\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			cfg.maxDepth = n
		case arg == "-E" || arg == "--no-extension":
			cfg.noExt = true
		case arg == "-g" || arg == "--generate":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: a value is required for '--generate <PATH>' but none was supplied\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			cfg.generate = args[i]
		case strings.HasPrefix(arg, "--generate="):
			cfg.generate = arg[11:]
		case arg == "-k" || arg == "--mkdir":
			cfg.mkdir = true
		case arg == "-m" || arg == "--map" || arg == "--from-file":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: a value is required for '--map <PATH>' but none was supplied\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			cfg.mapFile = args[i]
		case strings.HasPrefix(arg, "--map="):
			cfg.mapFile = arg[6:]
		case strings.HasPrefix(arg, "--from-file="):
			cfg.mapFile = arg[12:]
		case arg == "-q" || arg == "--quiet":
			cfg.quiet = true
		case arg == "-r" || arg == "--regex":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: a value is required for '--regex <PATTERN>' but none was supplied\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			cfg.regex = args[i]
		case strings.HasPrefix(arg, "--regex="):
			cfg.regex = arg[8:]
		case arg == "-s" || arg == "--sort":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: a value is required for '--sort <ORDER>' but none was supplied\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			val := args[i]
			if val != "asc" && val != "desc" {
				fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--sort <ORDER>'\n  [possible values: asc, desc]\n\nFor more information, try '--help'.\n", val)
				os.Exit(2)
			}
			cfg.sortOrder = val
		case strings.HasPrefix(arg, "--sort="):
			val := arg[7:]
			if val != "asc" && val != "desc" {
				fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--sort <ORDER>'\n  [possible values: asc, desc]\n\nFor more information, try '--help'.\n", val)
				os.Exit(2)
			}
			cfg.sortOrder = val
		case arg == "-t" || arg == "--test" || arg == "--dry-run":
			cfg.testMode = true
		case arg == "-w" || arg == "--overwrite":
			cfg.overwrite = true
		case arg == "--":
			i++
			for i < len(args) {
				cfg.posArgs = append(cfg.posArgs, args[i])
				i++
			}
			return cfg, false, false
		case strings.HasPrefix(arg, "-") && len(arg) > 1:
