		for out, sl := range outMap {
			indexed = append(indexed, indexedRename{
				re:          renameEntry{input: sl.input, output: out, conflicted: sl.conflicted},
				insertOrder: sl.insertOrder,
			})
		}
		sort.Slice(indexed, func(i, j int) bool {
			return indexed[i].insertOrder < indexed[j].insertOrder
		})

		// Now order: non-conflicting first (in sort order), conflicting last (in sort order)
		var nonConflicted, conflicted []renameEntry
		for _, ie := range indexed {
			if ie.re.conflicted {
				conflicted = append(conflicted, ie.re)
			} else {
				nonConflicted = append(nonConflicted, ie.re)
			}
