	var nonConflicted, conflicted []renameEntry
	for _, p := range pairs {
		re := renameEntry{input: p.input, output: p.finalOutput, conflicted: p.conflicted}
		if p.conflicted {
			conflicted = append(conflicted, re)
		} else {
			nonConflicted = append(nonConflicted, re)
		}
	}
