# Natural sort: file001 (1) < file01 (1) < file2 (2) < file10 (10)
# When numeric values are equal (001 = 01 = 1), the sort falls back to string comparison
# "file001" has digits "001" which equals 1 numerically
# "file01" has digits "01" which equals 1 numerically
# After the equal numerics, we compare the REMAINING strings: "" vs "" (same)
# Hmm, but file001 shows before file01... 
# Let me check my naturalLess logic for equal numbers

cat > /tmp/nat_test.go << 'EOF'
package main

import (
    "fmt"
    "strconv"
)

func naturalLess(a, b string) bool {
    for len(a) > 0 && len(b) > 0 {
        aDigit := a[0] >= '0' && a[0] <= '9'
        bDigit := b[0] >= '0' && b[0] <= '9'
        if aDigit && bDigit {
            ai := 0
            for ai < len(a) && a[ai] >= '0' && a[ai] <= '9' {
                ai++
            }
            bi := 0
            for bi < len(b) && b[bi] >= '0' && b[bi] <= '9' {
                bi++
            }
            aNum, _ := strconv.Atoi(a[:ai])
            bNum, _ := strconv.Atoi(b[:bi])
            if aNum != bNum {
                return aNum < bNum
            }
            a = a[ai:]
            b = b[bi:]
        } else if !aDigit && !bDigit {
            if a[0] != b[0] {
                return a[0] < b[0]
            }
            a = a[1:]
            b = b[1:]
        } else {
            return aDigit
        }
    }
    return len(a) < len(b)
}

func main() {
    pairs := [][2]string{
        {"001", "01"},
        {"01", "001"},
        {"file001.txt", "file01.txt"},
        {"file01.txt", "file001.txt"},
    }
    for _, p := range pairs {
        fmt.Printf("%s < %s? %v\n", p[0], p[1], naturalLess(p[0], p[1]))
    }
}
EOF
go run /tmp/nat_test.go

